CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS buses (id TEXT PRIMARY KEY, data JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS routes (id TEXT PRIMARY KEY, data JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS trips (id TEXT PRIMARY KEY, route_id TEXT NOT NULL REFERENCES routes(id), bus_id TEXT NOT NULL REFERENCES buses(id),departure TIMESTAMPTZ NOT NULL,arrival TIMESTAMPTZ NOT NULL,fare INTEGER NOT NULL CHECK(fare>=0),fee INTEGER NOT NULL CHECK(fee>=0),status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY,reference TEXT UNIQUE NOT NULL,access_hash TEXT NOT NULL,status TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'demo',trip_id TEXT NOT NULL REFERENCES trips(id),name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,pickup TEXT NOT NULL,dropoff TEXT NOT NULL,total INTEGER NOT NULL,fare INTEGER NOT NULL,fee INTEGER NOT NULL,idempotency TEXT UNIQUE NOT NULL,hold_id TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS inventory (trip_id TEXT NOT NULL REFERENCES trips(id),seat INTEGER NOT NULL,blocked BOOLEAN DEFAULT FALSE,hold_id TEXT,owner_hash TEXT,hold_expires TIMESTAMPTZ,booking_id TEXT REFERENCES bookings(id),PRIMARY KEY(trip_id,seat));
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),seat INTEGER NOT NULL,passenger TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,status TEXT DEFAULT 'issued',checked_in_at TIMESTAMPTZ,UNIQUE(booking_id,seat));
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY,password_hash TEXT NOT NULL,role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,staff_id TEXT NOT NULL REFERENCES staff(id),expires TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id BIGSERIAL PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,details JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS trips_departure_idx ON trips(departure);
CREATE INDEX IF NOT EXISTS inventory_booking_idx ON inventory(booking_id);
CREATE INDEX IF NOT EXISTS tickets_booking_idx ON tickets(booking_id);